      sections.push(bucket);
    }
    bucket.items.push(item);
  }
  const formatDate = (value) =&gt; {
    if (!value) return "";
    const d = new Date(value);
    return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
  };
